from paging import paginate


def test_first_page():
    assert paginate([1, 2, 3, 4, 5, 6, 7], 1, 3) == [1, 2, 3]


def test_second_page():
    assert paginate([1, 2, 3, 4, 5, 6, 7], 2, 3) == [4, 5, 6]


def test_last_page_returns_full_slice():
    assert paginate([1, 2, 3, 4, 5, 6, 7], 1, 3) == [1, 2, 3]


def test_past_the_end_returns_empty_list():
    assert paginate([1, 2, 3], 5, 3) == []


def test_page_below_one_is_handled():
    assert paginate([1, 2, 3], 2, 3) == []


def test_size_below_one_is_handled():
